UPDATE characters SET description = '保科宗四郎は防衛隊第三部隊の副隊長。のんびりとした性質とは裏腹に、非常に強力な能力を持ち、刀剣を使った戦闘を得意としている。保科宗四郎は室町時代に遡る怪獣退治の一族の出身である。', tags = ARRAY['黒髪','おっとり','剣士','マイペース']::text[], voice_actor = '河西健吾' WHERE character_id = 'CH004746'; -- 保科宗四郎
UPDATE characters SET description = '亜白ミナは防衛隊の非常に優秀なメンバーで、並外れた射撃の才能を持つ人物です。防衛隊第三部隊の隊長を務めています。幼少期、怪獣の襲撃後にカフカと出会い、二人で防衛隊に入隊して共に怪獣と戦うことを誓い合いました。', tags = ARRAY['黒髪','ポニーテール','お姉さん','軍服','クール','真面目','ヒロイン','幼馴染','社会人','銃使い','天才']::text[], voice_actor = '瀬戸麻沙美' WHERE character_id = 'CH004739'; -- 亜白ミナ
UPDATE characters SET description = '日比野カフカは、怪獣８号としても知られ、防衛隊の隊員であり、かつて民間怪獣清掃業者「モンスタースウィーパー」の作業員として働いていた。カフカの性格は少しおこちゃまで陽気なところがあり、同時に非常に芯の強い人間で、仲間思いである。怪獣が自身の体に侵入してしまったことをきっかけに、人型の怪獣に変身する能力を得た。', tags = ARRAY['黒髪','ショートヘア','元気','主人公','社会人','格闘家','人外']::text[], voice_actor = '福西勝也' WHERE character_id = 'CH004725'; -- 日比野カフカ
UPDATE characters SET description = '彼はモンスタースウィーパー社で働いていた時に、日比野カフカと出会い友人になった。その後、カフカの変身を目撃したレノは、彼が防衛隊に入隊するのを手助けし、自分も一緒に入隊した。', tags = ARRAY['黒髪','ショタ','社会人','真面目']::text[], voice_actor = '加藤渉' WHERE character_id = 'CH004727'; -- 市川レノ
UPDATE characters SET description = '彼女は防衛隊長官・四ノ宮勇の娘で、第三部隊に所属している。立川基地の崩壊後、四ノ宮キコルは第一部隊に配属される。', tags = ARRAY['ロリ','黒髪','高校生','軍服']::text[], voice_actor = 'ファイルーズあい' WHERE character_id = 'CH004726'; -- 四ノ宮キコル
UPDATE characters SET description = '鳴海弦は防衛隊第一師団の師団長である。日本最強の怪獣対策戦士として知られており、その地位に至っている。鳴海弦は怠け癖があり、子どもっぽい性格をしており、SNSのフォロワー数やゲーム、アクションフィギュアに執着している。他者との対面では、ぶっきらぼうで失礼な態度を見せることが多い。しかし仕事に対しては真摯であり、スキルを何より重視し、師団に仕える者全員に成果を求める厳しい一面を持つ。', tags = ARRAY['クール','真面目','マイペース','S属性','ナルシスト','社会人']::text[], voice_actor = '内山昂輝' WHERE character_id = 'CH004742'; -- 鳴海弦
UPDATE characters SET description = '古橋伊春は、防衛隊第三部隊の若き隊員である。', tags = ARRAY['黒髪','ショタ','制服','真面目','社会人']::text[], voice_actor = '新祐樹' WHERE character_id = 'CH004735'; -- 古橋伊春
UPDATE characters SET description = '四ノ宮功は防衛隊の局長であり、四ノ宮琴露の父親である。四ノ宮功は非常に威厳があり真摯な人物で、部下にも娘にも厳しい要求を課す。防衛隊の局長として長年その組織に身を置いてきた四ノ宮功は、先見の明を持ち、将来の脅威を見据えた上で毅然たる指示を下す人間である。生きた怪獣を防衛隊の力を強化するための兵器として利用することも辞さない。冷徹で真摯な振る舞いとは裏腹に、四ノ宮功は怪獣合成人間・火ノ丸カフカについての琴露の言葉を思い出した時や、彼が～', tags = ARRAY['白髪','おじさん','真面目','クール','父親','社会人','軍服']::text[], voice_actor = '玄田哲章' WHERE character_id = 'CH004750'; -- 四ノ宮功
UPDATE characters SET description = '職業：第三部隊の作戦参謀

小此木このみは、意志が強く仕事に厳密な人物だ。星野宗四郎の不真面目な発言や不意の笑いには同意できないようだが、彼のことを心からケアしており、誰もが危機に直面する際には誰もかれもを気にかけている。その代わり、彼女は星野宗四郎から高く評価されている。仕事中、このみは専門的で真摯な態度を示し、現在の状況を素早く把握して同僚のサポートに当たる。また、優れた直感力と分析能力を発揮している。', tags = ARRAY['黒髪','真面目','クール','社会人']::text[], voice_actor = '千本木彩花' WHERE character_id = 'CH004743'; -- 小此木このみ
UPDATE characters SET description = '伐虎は芦野ミナに飼われているトラである。伐虎は極めて落ち着いた性格で、飼い主のミナに絶対的に従順である。戦闘中でもミナの側に常に付き添っており、怪獣に対抗でき、あるいは倒すことすら可能な強さを持つものと推察される。', tags = ARRAY['獣耳(その他)','しっぽ','おっとり','人外']::text[] WHERE character_id = 'CH004744'; -- 伐虎
