UPDATE characters SET description = '万次郎は霊媒師で、「ツチノコ」を祀る神社の神主を務めている。しかし実際にそこに祀られているのは、昔からこの地域で信仰されていた大蛇が脱ぎ捨てた皮なのだ。密かにBooTuberになることを夢見ている。', tags = ARRAY['黒髪','おじさん','巫女']::text[], voice_actor = '吉野裕行' WHERE character_id = 'CH009777'; -- 万次郎
