UPDATE characters SET description = 'フリーレンは『葬送のフリーレン』の主人公であり、フェルンの師匠である。勇者パーティーの魔法使いとして、勇者ヒンメル、戦士アイゼン、司祭ハイターとともに魔王を倒すための10年間の旅に出かけた。幼い頃から魔法の才能を示し、膨大な魔力を備えていたことから、人間の魔法使いフラメに目をつけられ、彼女の死まで魔法と魔力制御のすべてを教わった。フリーレンは些細なものであっても、魔法知識を集め続けることに執着している。', tags = ARRAY['銀髪','ロングヘア','お姉さん','細身','クール','主人公','魔法使い','エルフ']::text[], voice_actor = '種﨑敦美' WHERE character_id = 'CH011333'; -- フリーレン
