UPDATE characters SET description = '魔王を倒した勇者パーティーのリーダーで、自称イケメンナルシスト。仲間を思いやり、困っている者を放っておけない性分。フリーレンとは10年間の冒険を共にし、彼女に大きな影響を与えた。', tags = ARRAY['金髪','長身','ナルシスト','勇者']::text[], voice_actor = '岡本信彦' WHERE character_id = 'CH011342'; -- ヒンメル
UPDATE characters SET description = 'レヴォルテは「神聖なる反逆者」とも呼ばれる魔族の将軍である。レヴォルテは魔力で作られた4本の剣を操る。', tags = ARRAY['魔法使い','剣士','悪役','人外','長身','おじさん']::text[], voice_actor = '三木眞一郎' WHERE character_id = 'CH011341'; -- レヴォルテ
