UPDATE characters SET description = 'エーデルは第一級魔法試験に参加する「十七番隊」に所属する二級魔法使いで、ブレイとダンストと共に行動している。彼女は催眠魔法を得意とする。', tags = ARRAY['魔法使い']::text[], voice_actor = '黒沢ともよ' WHERE character_id = 'CH011337'; -- エーデル
UPDATE characters SET description = '一級魔法使い試験の第一段階で第八班を率いる二級魔法使い。北方魔導団の団長であり、非常に経験豊富な魔法使い。相手の姿が見えている状態での拘束魔法を得意としている。', tags = ARRAY['おじさん','魔法使い','クール','真面目']::text[], voice_actor = '谷山紀章' WHERE character_id = 'CH011354'; -- ヴィアベル
UPDATE characters SET description = '勇者パーティーの一員だったドワーフの戦士で、後にスタルクの師匠となった人物。', tags = ARRAY['おじさん','筋肉質','剣士']::text[], voice_actor = '上田燿司' WHERE character_id = 'CH011346'; -- アイゼン
UPDATE characters SET description = NULL, tags = ARRAY['おじさん','社会人']::text[], voice_actor = '大川透' WHERE character_id = 'CH011340'; -- ゲーエン
UPDATE characters SET description = 'ロキシー・ミグルディアはミグルド族の優秀な魔術師であり、元々は魔法の家庭教師を務めていた。テレパシーが使えないため、同族から孤立していると感じ、故郷を離れることになった。冒険者として安定した生活が得られず、放浪しながら家庭教師の仕事をするようになり、やがてルーデウスの師匠となる。', tags = ARRAY['銀髪','お姉さん','魔法使い','教師','クール']::text[], voice_actor = '小原好美' WHERE character_id = 'CH004801'; -- ロキシー・ミグルディア
UPDATE characters SET description = 'ルーデウス・グレイラットは背が高く、筋骨隆々とした、クールな印象の男性です。しかし、転生する前の前世では、高校時代のいじめをきっかけに引きこもった、太った34歳の日本人ニートでした。そうした過去があるため、彼は調子に乗って傲慢にならないよう気をつけています。その結果、昔の自分に戻りたくないという思いから、非常に自分に厳しく謙虚な姿勢を貫いています。彼は親切心の厚い人物で、友人を助け、必要とあれば家族を守ります。多くの分野で能力を発揮していることから、周囲から高い期待を寄せられています。彼の現在の体は', tags = ARRAY['黒髪','長身','筋肉質','クール','真面目','主人公','異世界転生','魔法使い']::text[], voice_actor = '内山夕実' WHERE character_id = 'CH004797'; -- ルーデウス・グレイラット
UPDATE characters SET description = 'シルフィエットはルーデウスの幼馴染で、人間、エルフ、獣族の血を引くハーフである。', tags = ARRAY['金髪','ロングヘア','幼馴染','エルフ','人外']::text[], voice_actor = '茅野愛衣' WHERE character_id = 'CH004798'; -- シルフィエット
UPDATE characters SET description = 'ルイジェルド・スペルディアは、かつてラプラスに絶対の忠誠を誓うスペルド戦士団の元指導者であり、ルーデウスとエリスに同行していた。', tags = ARRAY['白髪','長身','おじさん','クール']::text[], voice_actor = '浪川大輔' WHERE character_id = 'CH004819'; -- ルイジェルド・スペルディア
UPDATE characters SET description = 'パウロ・グレイラットはルーデウス・グレイラット、ノルン・グレイラット、アイシャ・グレイラットの父親である。彼は若い頃から三大剣術すべてを極めた才能ある男であり、同時にゼニスに縛られるまで多くの女性を惹きつけ関係を持つ好色漢でもある。', tags = ARRAY['黒髪','長身','おじさん','父親','剣士','ナルシスト']::text[], voice_actor = '森川智之' WHERE character_id = 'CH004812'; -- パウロ・グレイラット
UPDATE characters SET description = 'ゼニス・グレイラットはポール・グレイラットの妻であり、ルーデウス・グレイラットとノルン・グレイラットの母親である。', tags = ARRAY['母親']::text[], voice_actor = '金元寿子' WHERE character_id = 'CH004809'; -- ゼニス・グレイラット
UPDATE characters SET description = 'アイシャ・グレイラットはリリアとポール・グレイラットの娘であり、ルーデウス・グレイラットとノルン・グレイラットの妹である。', tags = NULL, voice_actor = '高田憂希' WHERE character_id = 'CH004814'; -- アイシャ・グレイラット
UPDATE characters SET description = 'エリナリーゼ・ドラゴンロードはポールのパーティの元メンバーである。彼女の呪いによる影響で色欲的な性質を持っている。モンスターの注意を引くことに長けた戦士だが、戦闘能力そのものは優れていない。', tags = ARRAY['金髪','ロングヘア','お姉さん','褐色肌','グラマー','小悪魔','人外']::text[], voice_actor = '田中理恵' WHERE character_id = 'CH004811'; -- エリナリーゼ・ドラゴンロード
UPDATE characters SET description = 'リーリャはグレイラット家の侍女である。剣士道場ではポールの同門だった。重傷を負ったことで王妃の護衛職を辞め、ポールとゼニスの侍女となった。', tags = ARRAY['剣士']::text[], voice_actor = 'Lynn' WHERE character_id = 'CH004820'; -- リーリャ
UPDATE characters SET description = '申し訳ありませんが、提供いただいた原文が「Light Novel Volume 9 spoiler」という表記のみで、実際の英語説明文が含まれていません。

七星静香についての英語説明文をご提供いただければ、翻訳ルールに従って自然な日本語に翻訳させていただきます。', tags = NULL, voice_actor = '若山詩音' WHERE character_id = 'CH004803'; -- 七星静香
UPDATE characters SET description = '薫子の良き友人であり、クラスメイト。紫京女学園の生徒。厳格で優秀な一族に育てられた沢渡亜由美は、自分のプライドを守るため、千鳥公立高校の生徒たちについての否定的な噂に頼ってきた。', tags = ARRAY['黒髪','高校生','お嬢様','ツンデレ','真面目']::text[], voice_actor = '水野朔' WHERE character_id = 'CH009795'; -- 沢渡亜由美
UPDATE characters SET description = '紫京学園の優秀な生徒。和栗薫子は非常に頭がよく心優しい一方で、抜けた一面もある。甘いお菓子を食べることが大好きで、凛太郎の実家のケーキ屋で彼と出会い、すぐに仲良くなった。その後、凛太郎が自分の学園と対立関係にある千鳥高校に通っていることを知っても、彼との親密な関係を変わらず大切にしている。', tags = ARRAY['黒髪','高校生','天然','ドジ','ヒロイン','お嬢様']::text[], voice_actor = '井上ほの花' WHERE character_id = 'CH009784'; -- 和栗薫子
UPDATE characters SET description = '千鳥高校の生徒で、綾人と咲とともに凛太郎の親友。翔平は非常に社交的で、凛太郎の友人グループの中で最もよく喋るメンバーである。また、対立校である菊代の生徒たちが激しく反発しているにもかかわらず、翔平は菊代の学生に対して敵意を一切抱いていない。', tags = ARRAY['高校生','元気']::text[], voice_actor = '戸谷菊之介' WHERE character_id = 'CH009791'; -- 宇佐美翔平
UPDATE characters SET description = '千鳥高校の生徒。紬凛太郎は非常に優しく穏やかな人物だが、幼い頃の自分らしさを表現する葛藤から得た金髪とピアスのせいで、多くの人から不良と見なされてしまっている。そんな中、千鳥高校の親友たちと、対立校である桔梗学園の女子生徒・薫子だけは彼を理解している。家族経営のケーキ屋で薫子と初めて出会った紬凛太郎は、やがて彼女と過ごす時間が増えていく。', tags = ARRAY['金髪','高校生','おっとり','幼馴染']::text[], voice_actor = '中山祥徳' WHERE character_id = 'CH009785'; -- 紬凛太郎
UPDATE characters SET description = '千鳥高校の生徒で、咲とともにりん太郎の親友。依田絢斗はとても気さくな性格をしており、暴力的な状況は避けたいと考えているものの、自分の身は十分に守ることができ、友人が脅かされるようなことがあれば惜しみなく立ち向かう。', tags = ARRAY['黒髪','高校生','元気','ボーイッシュ','幼馴染']::text[], voice_actor = '石橋陽彩' WHERE character_id = 'CH009794'; -- 依田絢斗
UPDATE characters SET description = '凛太郎の父親。妻の京子と共に紬家のベーカリーを経営している。パン職人としての仕事に身を捧げており、ほぼ毎日厨房に立って自らの技術を磨き続けている。', tags = ARRAY['おじさん','父親','社会人']::text[], voice_actor = '置鮎龍太郎' WHERE character_id = 'CH009792'; -- 紬圭一郎
UPDATE characters SET description = '香子の友人で、桔梗学園の生徒。', tags = ARRAY['黒髪','高校生']::text[], voice_actor = '下地紫野' WHERE character_id = 'CH009796'; -- 浅倉すずか
UPDATE characters SET description = NULL, tags = NULL, voice_actor = '大塚剛央' WHERE character_id = 'CH009790'; -- 高橋友誠
UPDATE characters SET description = '千鳥高校の生徒で、翔平と綾人と共に凛太郎の親友。容姿は整っているものの、いつも沈んだ表情をしており、話しかけにくい雰囲気を漂わせている。友人たちより内向的だが、その斜に構えた態度の裏には友人たちを深く思いやる心と生来の優しさを持っている。また、頭脳明晰で、千鳥高校で最も成績優秀な生徒であり、翔も一緒に勉強を始めるほど、桔梗の学舎の生徒たちをも凌ぐ実力の持ち主である。', tags = ARRAY['黒髪','高校生','クール','無口','真面目','天才','幼馴染']::text[], voice_actor = '内山昂輝' WHERE character_id = 'CH009793'; -- 夏沢朔
UPDATE characters SET description = '桐杜高校に通う柚原まどかは、薫子の良き友人です。非常に明るく社交的で、桐杜学園の他の生徒たちとは異なり、知鳥高校の生徒たちに対して敵意や悪感情を持っていません。', tags = ARRAY['黒髪','高校生','元気']::text[], voice_actor = '土屋李央' WHERE character_id = 'CH009787'; -- 柚原まどか
UPDATE characters SET description = 'アリサ・ミハイロヴナ・九条は、学年トップの成績を誇る優等生で、生徒会の会計を務めている。愛称はアーリャで、マリア・ミハイロヴナ・九条の妹である。学年で最も美しい女子の一人であり、その冷たく距離を置いた態度から「孤高の姫君」と呼ばれている。アリサ・ミハイロヴナ・九条は努力を惜しまない性格で、努力しない人間を嫌う傾向がある。幼少期、クラスメイトの無気力さに失望し、彼らの無知さを認識するようになった。', tags = ARRAY['金髪','ロングヘア','つり目','細身','高校生','制服','ツンデレ','クール','真面目','お嬢様','ヒロイン','天才']::text[], voice_actor = '上坂すみれ' WHERE character_id = 'CH006068'; -- アリサ・ミハイロヴナ・九条
UPDATE characters SET description = '久世政近は、やる気を失った成績不振の生徒で、毎晩遅くまでオタ趣味に没頭している。クラスで隣に座るアーリャさんから、いつも厳しく指摘されている。成績は決して良くないが、ロシア文化を愛する父方の祖父の影響で、実はロシア語が理解できる。', tags = ARRAY['黒髪','ショタ','制服','中学生']::text[], voice_actor = '天崎滉平' WHERE character_id = 'CH006069'; -- 久世政近
UPDATE characters SET description = NULL, tags = ARRAY['黒髪','ショートヘア','ショタ','主人公']::text[], voice_actor = '辻親八' WHERE character_id = 'CH006077'; -- 久世知久
UPDATE characters SET description = '高校1年生。清佳とは幼馴染みの親友。', tags = ARRAY['高校生','幼馴染']::text[], voice_actor = '青山吉能' WHERE character_id = 'CH006071'; -- 宮前乃々亜
UPDATE characters SET description = '周防有希は、旧貴族の家系に生まれた気品ある令嬢である。現在は生徒会の広報を務めており、中学時代は生徒会長を経験している。学年随一の美少女二人の一人であり、「高潔な姫君」と呼ばれている。真佐彦とは幼馴染である。', tags = ARRAY['黒髪','ロングヘア','高校生','お嬢様','クール','幼馴染','生徒会長']::text[], voice_actor = '丸岡和佳奈' WHERE character_id = 'CH006076'; -- 周防有希
UPDATE characters SET description = 'マリヤ・ミハイロヴナ・九条は2年生で、生徒会書記を務めている。愛称はマーシャで、アーリャ・ミハイロヴナ・九条の実姉である。学年きっての美女の一人として知られている。容姿と母親のような優しいオーラで人気があり、学園の「マドンナ」と呼ばれている。マーシャがアーリャの周りでわざとおっとりした様子を見せるのは、彼女と競い合いたくないからである。妹をとても愛しているからこそ、このような態度をとっているのだ。実際には、彼女の内面は非常に成熟で真摯である。政近はそんな彼女の本心を読み取るのに苦労している。', tags = ARRAY['金髪','ロングヘア','高校生','お姉さん','制服','おっとり','真面目','ヒロイン']::text[], voice_actor = '藤井ゆきよ' WHERE character_id = 'CH006070'; -- マリヤ・ミハイロヴナ・九条
UPDATE characters SET description = '君嶋綾乃は周防家に仕える無表情なメイド。主人に対して限りない愛情を持つ献身的な使用人で、ユキへの奉仕に身を捧げている。存在感が薄く、いつの間にか消えてしまうことが多い。', tags = ARRAY['黒髪','ロングヘア','メイド服','クール','無口','執事']::text[], voice_actor = '会沢紗弥' WHERE character_id = 'CH006073'; -- 君嶋綾乃
UPDATE characters SET description = '現在の高校の生徒会を率いるカリスマ的な生徒会長。現在、高校2年生である。', tags = ARRAY['黒髪','高校生','生徒会長','クール']::text[], voice_actor = '石川界人' WHERE character_id = 'CH006079'; -- 剣崎統也
