UPDATE characters SET description = '彼女は中学時代に生徒会長の座をユキと争った、現在の風紀委員である。', tags = ARRAY['黒髪','ライバル','中学生']::text[], voice_actor = '長谷川育美' WHERE character_id = 'CH006080'; -- 谷山沙也加
UPDATE characters SET description = '子昌は現在の宰相であり、史一族の当主です。彼の狡猾さは、もともと取るに足らない身分から、国内でも有数の影響力を持つ人物へと彼を成り上がらせました。しかし、自分が婿入りした史一族の内部では、その影響力を行使しようとはしません。', tags = ARRAY['黒髪','おじさん','クール','悪役','社会人','天才']::text[], voice_actor = 'チョー ' WHERE character_id = 'CH008087'; -- 子昌
UPDATE characters SET description = NULL, tags = NULL, voice_actor = '引坂理絵' WHERE character_id = 'CH008085'; -- 桜花
UPDATE characters SET description = '現在の皇帝は、求められた役割を果たしている。彼は強姦によって生まれた子であるため、母親である皇太后から嫌われている。最も信頼できる関係は、裏で細々とした事柄を処理してくれる兄との間にある。', tags = ARRAY['おじさん','クール']::text[], voice_actor = '遠藤大智' WHERE character_id = 'CH008062'; -- 皇帝
UPDATE characters SET description = '羅半はラカンの養子で、数字を愛する風変わりな人物である。', tags = ARRAY['男の娘','天才','マイペース']::text[], voice_actor = '豊永利行' WHERE character_id = 'CH008064'; -- 羅半
UPDATE characters SET description = '神美は、かつての史一族の当主の娘で、現在の史一族当主にして宰相である史昭の正妻であり、妃ルーランの母である。', tags = ARRAY['母親']::text[], voice_actor = '深見梨加' WHERE character_id = 'CH008077'; -- 神美
UPDATE characters SET description = '女華は緑青館の三姫の中で最年少であり、猫猫の義姉の一人である。', tags = ARRAY['お姉さん']::text[], voice_actor = '七海ひろき' WHERE character_id = 'CH008088'; -- 女華
UPDATE characters SET description = '虞淵は現在の後宮の侍医である。後宮での勤務を許可される条件として去勢を受ける必要があることは、多くの医師の志望を集めない。腕前はそこまで優れていない虞淵だったが、妹が無理やり後宮の侍女にされることを防ぐため、このような苛酷な条件での雇用を受け入れたのだ。', tags = ARRAY['黒髪','社会人']::text[], voice_actor = 'かぬか光明' WHERE character_id = 'CH008061'; -- 虞淵
UPDATE characters SET description = '姶良は姉妹のアイリンとともに、外国からの特使として派遣された人物である。', tags = NULL, voice_actor = 'Lynn' WHERE character_id = 'CH008089'; -- 姶良
UPDATE characters SET description = NULL, tags = NULL, voice_actor = '土井美加' WHERE character_id = 'CH008090'; -- 水蓮
UPDATE characters SET description = '壬氏は後宮の事務を統括する宦官である。その容貌は妃たちの美しさをも凌ぐほどと評され、男女を問わず周囲を魅了している。常に侍従の高順を侍らせており、猫猫の聡慧さと積極的な姿勢に関心を寄せている。', tags = ARRAY['黒髪','ロングヘア','細身','白肌','クール','ナルシスト']::text[], voice_actor = '大塚剛央' WHERE character_id = 'CH008059'; -- 壬氏
UPDATE characters SET description = '第1章の冒頭でスバルに襲いかかった3人の不良のうちの1人。', tags = ARRAY['社会人','悪役']::text[], voice_actor = '室元気' WHERE character_id = 'CH006903'; -- ラチンス・ホフマン
UPDATE characters SET description = 'オットー・スーウェンは『Re:ゼロから始める異世界生活』に登場する商人です。彼は常ならぬ不運に見舞われ、危機的な状況に陥ることが多いですが、その機転の良さでなんとか切り抜けています。オットーはギャルゲーの主人公並みに長いと評される灰色の髪が特徴です。真顔になるとそこそこ整った顔立ちをしているらしいのですが、普段は言い返したり、叫んだり、パニックに陥ったりしているため、その魅力が台無しになってしまっています。体格は中肉中背ですが、商人としての仕事をしていた時代から自分自身を鍛えてきました。', tags = ARRAY['グレー髪','ロングヘア','社会人','ドジ','不運']::text[], voice_actor = '天崎滉平' WHERE character_id = 'CH006902'; -- オットー・スーウェン
UPDATE characters SET description = 'ガーフィール・ティンゼルは、聖域の元守護者であり、エミリア陣営のメンバーです。第4章で登場し、シーズンの重要な脇役の一人となります。彼は半獣人であり、フレデリカ・バウマンの異母兄弟です。巨大な黄金の虎に変身することができ、強力な攻撃を繰り出せますが、理性を失う代償があるため、追い詰められた時にこの能力を使用します。', tags = ARRAY['金髪','ショタ','獣耳(その他)','筋肉質','中学生','ボーイッシュ','人外']::text[], voice_actor = '岡本信彦' WHERE character_id = 'CH006909'; -- ガーフィール・ティンゼル
UPDATE characters SET description = 'ミミ・パールバトンはアナスタシア・ホーシンの従者の一人であり、傭兵団「鋼の牙」の三人の副隊長の一人である。', tags = ARRAY['ロリ']::text[], voice_actor = '藤井ゆきよ' WHERE character_id = 'CH006882'; -- ミミ・パールバトン
UPDATE characters SET description = 'ライ・バテンカイトスは魔女教の罪司教であり、暴食の「美食」という側面を象徴している。彼は背が低く、薄茶色の長い髪と緑色の瞳を持ち、歯は鋭い牙のような形状をしている。青紫色の衣服と魔女教のロープを身に纏っているが、どちらも極めて汚れており、血痕で染まっている。また、教団から授けられた短剣を両手に装着している。', tags = ARRAY['茶髪','ロングヘア','緑髪','八重歯','小柄','悪役','魔法使い']::text[], voice_actor = '河西健吾' WHERE character_id = 'CH006894'; -- ライ・バテンカイトス
UPDATE characters SET description = NULL, tags = ARRAY['母親','お姉さん']::text[], voice_actor = '水樹奈々' WHERE character_id = 'CH006893'; -- リリアナの母
UPDATE characters SET description = 'リカード・ウェルキンはアナスタシア・ホーシンの配下の一人であり、傭兵団「鉄牙」の隊長である。', tags = ARRAY['おじさん','社会人']::text[], voice_actor = '乃村健次' WHERE character_id = 'CH006908'; -- リカード・ウェルキン
UPDATE characters SET description = 'シリウスは魔女教の大罪司教の一人で、怒りを司る。', tags = ARRAY['紫髪','悪役','魔法使い','人外']::text[], voice_actor = '安済知佳' WHERE character_id = 'CH006883'; -- シリウス・ロマネコンティ
UPDATE characters SET description = 'ヴィルヘルム・ヴァン・アストレアは、クルシュ陣営の一員であり、テレシア・ヴァン・アストレアの夫です。ヴィルヘルムは洗練された物腰で、非常に穏やかで謙虚な人物です。しかし、その落ち着いた態度の奥底には、何か事が起きると真っ先に駆けつける猛き戦士の姿が隠されています。もっとも、これが常にそうであったわけではありません。若き日のヴィルヘルムは、後年の彼とは正反対の人物でした。無謀で落ち着きがなく、短気で孤独、そして他者に対して冷淡でした。剣に一身を捧げ、他のことにはほとんど目を向けない、問題を抱えた青年だったのです。しかし同時に、彼は状況を分析する能力を備えていました。', tags = ARRAY['白髪','おじさん','真面目','クール','剣士','騎士']::text[], voice_actor = '堀内賢雄' WHERE character_id = 'CH006876'; -- ヴィルヘルム・ヴァン・アストレア
UPDATE characters SET description = 'アルデバランは通称「アル」と呼ばれ、プリシラ・バリエルの騎士である。本人は単なる部下だと主張しているが、軽薄な性格で素っ気ない態度をとる一方、傷跡のある顔についての不安を抱いており、それを隠すためにヘルメットを被っている。そのため、彼は外見・言動ともに一風変わった男である。', tags = ARRAY['男の娘','騎士','ナルシスト','マイペース']::text[], voice_actor = '関智一' WHERE character_id = 'CH006877'; -- アルデバラン
UPDATE characters SET description = '桜遥は高校1年生の男子生徒。不良校として知られる風林高校に通っており、頂点を目指す野心を持っている。強い人間に憧れている。粗野な外見のため周囲から敬遠され、孤独でいることが自然な状態だった。他者から嫌われ、社会的地位の底辺にいる桜遥は、喧嘩こそが自分の唯一の救いであり、その喧嘩に勝つことで自分の価値を感じられると信じている。無慈悲で強面な外見を保とうとしているが、実際には心優しい少年である。良い行いを褒められると、すぐに照れてしまう。', tags = ARRAY['黒髪','ショートヘア','高校生','筋肉質','ボーイッシュ','クール','ハジデレ','格闘家']::text[], voice_actor = '内田雄馬' WHERE character_id = 'CH004822'; -- 桜遥
UPDATE characters SET description = '風林高校1年1組の生徒である蘇枋隼飛。爽やかな笑顔と誰に対しても親切な態度が特徴だが、突拍子もないジョークで周囲を混乱させることもある。その親しみやすさとは裏腹に、礼儀を欠く人間には容赦ない冷酷な一面を見せることもある。蘇枋隼飛は普段感情を表に出さず本心を明かさないため、正体不明の謎めいた人物である。彼の戦闘スタイルは、カンフーとaikidoの両方の特徴を兼ね備えた独特なものだ。', tags = ARRAY['高校生','クール','無口','格闘家']::text[], voice_actor = '島﨑信長' WHERE character_id = 'CH004827'; -- 蘇枋隼飛
UPDATE characters SET description = '風林高校1年3組の3年生。梅宮一は暴風林（ボフーリン）の代表であり、その頂点に立つ人物である。爽やかな笑顔と親しみやすい人柄で、風林高校の生徒たちだけでなく、町の人々からも絶対的な信頼を勝ち取るカリスマ的な存在だ。ただし、彼の強さは身体能力だけではない。どんな状況にも対処できる不屈の精神力を備えており、一声発するだけで周囲の者たちを圧倒する力を持っている。趣味は野菜を育てることである。', tags = ARRAY['黒髪','高校生','先輩','クール','天才','格闘家']::text[], voice_actor = '中村悠一' WHERE character_id = 'CH004833'; -- 梅宮一
UPDATE characters SET description = 'シシトレンのナンバー2。作業着と日本の木製下駄を身に着け、サングラスの奥に目を隠した十亀条は、ゆっくりとした口調で話す。残忍で容赦ない性格の持ち主だ。シシトレンに既に属していたとしても、弱者は居場所がないというトミヤマの信念を忠実に実行している。彼は桜を人気ボードゲーム「オセロ」になぞらえて「オセロくん」と呼び、からかっている。', tags = ARRAY['黒髪','高校生','筋肉質','クール','S属性','悪役']::text[], voice_actor = '梅原裕一郎' WHERE character_id = 'CH004836'; -- 十亀条
UPDATE characters SET description = NULL, tags = ARRAY['黒髪','ショートヘア','クール','高校生']::text[], voice_actor = '岡本信彦' WHERE character_id = 'CH004828'; -- 梶蓮
UPDATE characters SET description = '橘ことははカフェ・ポトスで働いている。親しみやすく勇敢な性格のため大人っぽく見えるが、桜たちと同じく16歳である。カフェ・ポトスのマネージャーとして、毎日風林高校の生徒と地元の人々に最高のメニューを提供している。時には桜の行動に対して注意することもある。', tags = ARRAY['黒髪','高校生','元気','真面目','社会人']::text[], voice_actor = '長谷川育美' WHERE character_id = 'CH004823'; -- 橘ことは
UPDATE characters SET description = '風林高校1年生の1組に属する生徒。優しい性格と思慮深さで女性からの人気が高い桐生三輝だが、決して甘くはなく、その戦闘能力は本物である。ゲーム好きで、空き時間があればプレイするのが日課で、ゲームのログインボーナスを取得することを習慣としている。親しい友人の名前に「ちゃん」を付けて呼ぶのが好きである。同学年の五傑の一人として敬われている。', tags = ARRAY['黒髪','高校生','真面目','天才','格闘家']::text[], voice_actor = '豊永利行' WHERE character_id = 'CH004839'; -- 桐生三輝
UPDATE characters SET description = '風林高校1年1組の生徒。新伊礼は格闘は弱いが、率直で素直な性格が教室の雰囲気を明るくしており、クラスの人気者だ。町を守ることにあらゆる誰よりも執着しており、ずっと風林高校への入学を目指していた。新伊礼はいつも胸ポケットにメモ帳とペンを持ち歩いており、情報通で、自分がかっこいいと思う人物のデータ収集と分析が趣味である。', tags = ARRAY['黒髪','高校生','元気','真面目']::text[], voice_actor = '千葉翔也' WHERE character_id = 'CH004830'; -- 楡井秋彦
UPDATE characters SET description = '風林高校1年1組の生徒。杉下は野獣のような存在で、才能に恵まれている。中学時代から「暴府輪」を名乗ることを許された唯一の存在だ。彼の行動力と原動力は、梅宮への絶対的な忠誠と献身から生まれている。梅宮の言葉が彼の全てである。普段は寡黙で、独特なリズムで歩く。だが一度怒ると、誰よりも予測不可能な力を発揮する。', tags = ARRAY['黒髪','高校生','無口','マイペース','筋肉質','天才']::text[], voice_actor = '内山昂輝' WHERE character_id = 'CH004825'; -- 杉下京太郎
UPDATE characters SET description = '風林高校3年1組の生徒。風林の四天王の一人で、多門チームのリーダーを務める柊登馬。神経質で責任感が強く、度量の大きい梅宮にいいように振り回されることが多い。胃薬が手放せないほどの働き者でもある。本物の格闘能力を持ち、その道の第一人者として証明されている。梅宮を心から支える理解者でもある。', tags = ARRAY['黒髪','高校生','真面目','格闘家']::text[], voice_actor = '鈴木崚汰' WHERE character_id = 'CH004835'; -- 柊登馬
UPDATE characters SET description = '一之瀬のクラスの生徒。', tags = ARRAY['高校生']::text[] WHERE character_id = 'CH003787'; -- 墨田誠
UPDATE characters SET description = '綾小路清隆は、目立たない存在の学生である。彼は極めて高い知能を持ち、周囲の人間の感情を深く洞察する能力に優れている。入学試験前の彼の人生のほぼすべてが謎に包まれている。彼は極めて計算高く、人間離れした知能、知覚力、身体能力を備えている。格闘技に優れており、周囲の人間を容易に操ることができる。彼は友人たちに好意を持ち、目立たない範囲で彼らを守ろうとする。一方で他者の気持ちにはほぼ無関心で、成功のためなら他人の苦しみを冷徹に放置することもある。', tags = ARRAY['黒髪','高校生','長身','制服','クール','無口','天才','格闘家','S属性']::text[] WHERE character_id = 'CH003742'; -- 綾小路清隆
UPDATE characters SET description = '綾小路の隣に座る美少女。友情に関してはAyanokoujiと正反対で、友人関係を軽視し、友達を作る必要性を感じていないため、クラスメイトとの交流が少ない。D組への配置に納得していないため、A組への昇級を目指している。', tags = ARRAY['黒髪','ロングヘア','高校生','細身','クール','真面目','ツンデレ','ライバル','お嬢様']::text[] WHERE character_id = 'CH003744'; -- 堀北鈴音
UPDATE characters SET description = '一之瀬帆波を一言で表すなら、心からの優しさと善意を持ち、根っからの平和主義者で、姑息な手段や暴力を否定する人物である。彼女の主な特徴は、無私の心と人を支援したいという姿勢を持ち、優れた対人スキルと生まれ持った人付き合いの上手さが組み合わさっていることだ。また、一之瀬帆波はカリスマ的で活動的な人物であり、多くの上流階級の生徒と異なり、下位クラスの者たちに対しても優しく穏やかな人柄を向けている。', tags = ARRAY['黒髪','ロングヘア','高校生','細身','白肌','元気','ヒロイン','おっとり','お嬢様','デレデレ']::text[] WHERE character_id = 'CH003745'; -- 一之瀬帆波
UPDATE characters SET description = '坂柳有栖は香礼と共に1年A組の学級委員を務めている。先天性心疾患を抱えており、身体能力に制限がある。香礼が学級の成績について指摘した後、つまらない状況が嫌だと口にするなど、ほとんどの状況を異議を唱えずに受け入れる「流れに身を任せる」態度を持っているようにも見える。保守的な立場をとる香礼とは異なり、坂柳有栖は革新的な姿勢を持っている。二人は協力してA組を学園生活へと効果的に導いている。彼女は興味深い状況を楽しむ傾向があり、その際の笑顔から窺える。', tags = ARRAY['黒髪','ショートヘア','小柄','高校生','制服','クール','マイペース','委員長','天才']::text[] WHERE character_id = 'CH003743'; -- 坂柳有栖
UPDATE characters SET description = '主人公のクラス（D組）の担任教師。元々は自分のクラスに対して無関心で、学年間の争いにおいてほぼ何もサポートせず、ほとんどやる気を見せていない。', tags = ARRAY['黒髪','ロングヘア','お姉さん','クール','教師','社会人']::text[] WHERE character_id = 'CH003781'; -- 茶柱佐枝
