UPDATE characters SET description = '喜多川海夢は派手で、だらしなく、大人びている一方で、どこか不器用なところがある。手先の器用さはあまり得意ではない。彼女はコスプレイヤーで、魔法少女アニメと大人向けのゲームが大好きな大のオタク。非常に優しく、人当たりがよく、いつも明るく社交的だ。食べることが大好きで、それでいてスリムな体型をキープしている。', tags = ARRAY['茶髪','ロングヘア','細身','元気','ドジ','ヒロイン','中学生']::text[], voice_actor = '直田姫奈' WHERE character_id = 'CH009797'; -- 喜多川海夢
