UPDATE characters SET description = '魔法工学の才能ある職人で、ウィルの相部屋。ウィルへの限りない好意はコレットを不安にさせるほど。工作の才能こそ生まれつきではないものの、優れた才能を身につけ、ウィルのためという名目でさまざまな魔法道具を開発することが多い。', tags = ARRAY['天才','高校生','真面目']::text[] WHERE character_id = 'CH006126'; -- ロスティ・ナウマン
UPDATE characters SET description = 'タワーの頂上にまで登り詰め、魔導師ヴァンダーの資格を得たが、別の候補者に敗北した上昇者。現在はレガルデン魔法学園の教授として、暗黒魔法と魔法史・魔法の起源を教えている。十年前、彼はまだ学生の身でありながら大戦に従軍した問題児グループの一員だった。', tags = ARRAY['黒髪','おじさん','教師','魔法使い','クール']::text[], voice_actor = '遊佐浩二' WHERE character_id = 'CH006125'; -- エドワルド・セルフェンス
