UPDATE characters SET description = 'サイタマは『ワンパンマン』の主人公であり、現存する最強のヒーローである。独自の修行によって超人的な肉体を手に入れたサイタマだが、誰もが敵わないほどの力を得てしまったため、ヒーロー活動にやりがいを感じられず、存在意義の危機に直面している。ヒーローズ協会にはB級ヒーローとして登録されており、Z市を怪人から守ることが任務である。ヒーローにしては珍しく、サイタマは非常にのんびりとした性格をしている。どんな強敵でも敵ではないため、ヒーローとしての仕事をあまり真剣に考えていない。しかし、そんな彼も常に自分に立ち向かえる対手を求めて', tags = ARRAY['白髪','ショタ','筋肉質','主人公','社会人','格闘家','マイペース','おっとり']::text[], voice_actor = '古川慎' WHERE character_id = 'CH010599'; -- サイタマ
UPDATE characters SET description = 'ガロウはバングの元弟子だが、暴走したため道場から追放されている。シリーズ最強キャラの一人であり、ヒーロー狩り編では主要な悪役として大きな役割を担っている。ガロウはヒーローへの憎悪と自信に満ちた復讐心の強い性格を持つ悪役として登場する。侮辱されることを嫌い、自分を貶める者には容赦なく攻撃を仕掛ける。自分自身を高く評価し、その自信でヒーローや幹部といった高い地位にある者たちを脅迫する。他の人間の悪役を味方とは見なさず、大人数の悪役を一掃している。', tags = ARRAY['黒髪','ショタ','筋肉質','悪役','格闘家','ナルシスト','S属性']::text[], voice_actor = '緑川光' WHERE character_id = 'CH010598'; -- ガロウ
