UPDATE characters SET description = '椿葉高校の1年生で、負けヒロインの一人。和彦のクラスでは人気者で、明るく魅力的な性格の持ち主。食欲旺盛で、体重のことを指摘されると和彦とよく口喧嘩になる。', tags = ARRAY['黒髪','元気','高校生','ヒロイン']::text[], voice_actor = '遠野ひかる' WHERE character_id = 'CH006154'; -- 八奈見杏菜
UPDATE characters SET description = '津波吹高校の1年生。女子陸上競技部のエース的存在であり、文芸部の部員でもある。長年の友人である綾野光月に好意を抱いており、現在は光月の彼女である朝雲千早と友人関係にある。', tags = ARRAY['高校生','ヒロイン']::text[], voice_actor = '若山詩音' WHERE character_id = 'CH006156'; -- 焼塩檸檬
UPDATE characters SET description = '椿吹高校の1年生で、文芸部に所属している。ウェブ小説やライトノベルの熱心な愛読者で創作活動もしている。一見すると内気で不器用に見えるが、実は努力家で、兄弟姉妹を大切にし、親しい人間関係を何よりも大事にしている。', tags = ARRAY['黒髪','高校生','真面目','ヒロイン','ドジ']::text[], voice_actor = '寺澤百花' WHERE character_id = 'CH006157'; -- 小鞠知花
UPDATE characters SET description = '温水和彦は津輪吹高校1年C組の生徒で、文芸部の部長を務めている。頭脳明晰で、妹の世話をしてきた経験から女の子の扱いにはかなり長けている。ただし、ファッションセンスは壊滅的で、より人気があり洗練された友人の柳美アンナからは呆れられている。', tags = ARRAY['黒髪','高校生','主人公','真面目','天才']::text[], voice_actor = '梅田修一朗' WHERE character_id = 'CH006155'; -- 温水和彦
