UPDATE characters SET description = '生徒会副会長。厳格で真面目な外見の裏には、興奮しやすく短絡的になりやすい性格が隠れており、予期しない展開に簡単に熱中してしまう傾向がある。月ノ木琴から没収した腐向け同人誌の内容を読んだことで、BLの世界に強い興味を持つようになり、ますます荒唐無稽になっていく妄想からの過剰刺激によって、頻繁に鼻血を出すようになってしまった。', tags = ARRAY['黒髪','真面目','高校生']::text[], voice_actor = '諸星すみれ' WHERE character_id = 'CH006170'; -- 馬剃天愛星
UPDATE characters SET description = '椿高校の３年生で、筋金入りの腐女子。文芸部の副部長であり、生徒会の前副会長。現在は豊橋外への大学進学に向けて準備中。玉木慎太郎の彼女であり、幼馴染でもある。', tags = ARRAY['黒髪','高校生','幼馴染','真面目']::text[], voice_actor = '種﨑敦美' WHERE character_id = 'CH006165'; -- 月之木古都
