UPDATE characters SET description = 'バヅムはレッド・サーカスのメンバーです。ビリー・スクワイアとともに、野外学習中のイーデン校のスクールバスを2台乗っ取り、バスに乗っていた生徒たちを人質に取りました。', tags = ARRAY['悪役','銃使い']::text[], voice_actor = 'こばたけまさふみ' WHERE character_id = 'CH010663'; -- バヅム
