UPDATE characters SET description = 'ヴァルカンジョゼフは動物を愛する非常に優秀なエンジニアで、その機械の多くは動物をモチーフにして製作している。人生の目標は、家族が開発したアマテラスのような装置を完成させ、世界に十分なエネルギーを供給することで、絶滅危機に瀕した動物たちを救うことである。崇高な理想を抱きながらも、彼は独立した立場を保つことを望んでいる。ヴァルカンジョゼフは自身の職業に情熱的であり、新しい発明を生み出すことを何よりも愛している。', tags = ARRAY['天才','社会人','真面目','マイペース']::text[], voice_actor = '八代拓' WHERE character_id = 'CH008896'; -- ヴァルカンジョゼフ
UPDATE characters SET description = '第二世代能力者。カロンは白装束の一員で、第二柱の守護者を務めている。福音者への強い忠誠心を持つ献身的な白装束メンバーのようだ。柱を守るという役割を極めて真摯に受け止めており、命がけでその責務を果たす。ハウメアが幼い頃から彼女の面倒を見てきたが、本人はその努力を特に評価していない様子。非常に耐久性に優れており、格闘戦の達人で、戦闘では自信に満ちており狡猾だ。', tags = ARRAY['おじさん','クール','真面目','悪役','格闘家']::text[], voice_actor = '安元洋貴' WHERE character_id = 'CH008897'; -- カロン
UPDATE characters SET description = 'メラメラは、マキ・オゼの第二世代能力で生み出された知性を持つ火の玉の一つである。', tags = ARRAY['人外']::text[], voice_actor = '小見川千明' WHERE character_id = 'CH008895'; -- メラメラ
