UPDATE characters SET description = '所属：特殊消防隊第8分隊 階級：科学班（一級消防士）研究部門長（火焔工業）

ヴィクトル・リヒトは第8分隊の科学職員である。彼は東京帝国大学に進学し、自然発火現象についての論文を執筆した。異例の速さで首席卒業を果たした後、火焔工業に入社した。研究に没頭する日々を過ごす中で、やがて自然発火現象研究の責任者に任命され、この分野の論文を発表している。やがてジョーカーがヴィクトル・リヒトに接触し、彼にある秘密を暴露したいと告げた。', tags = ARRAY['銀髪','メガネ','長身','大学生','社会人','天才']::text[], voice_actor = '阪口大助' WHERE character_id = 'CH008881'; -- ヴィクトル・リヒト
UPDATE characters SET description = '特殊消防隊第8分隊所属、階級は一等消防士。元軍人で、火炎を操る優れた戦闘能力を持つ。クールな女性だが恋愛ものには目がなく、その美貌は「頭の中が花とウェディングベルでいっぱい」という姿のせいで台無しになっている。友好的な性格だが、筋肉について指摘されるとキレてしまう。以前はスリムだったらしい。尾瀬茉希は第二世代の能力者で、自発的人体発火に適応することで、遠距離から炎を操る能力を身につけている。この力があれば、第三世代の能力者2人相手でも対応できる。', tags = ARRAY['クール','社会人','軍服','筋肉質','お姉さん','格闘家']::text[], voice_actor = '上條沙恵子' WHERE character_id = 'CH008849'; -- 尾瀬茉希
UPDATE characters SET description = '職業：プロヒーロー（エジプト第1位）個性：パピルス

エジプトナンバーワンのプロヒーロー。戦う姿を目撃したエジプト国民に安心感を与える独特のオーラを持つが、これまで彼の背中を見た者は誰もいない。サラームの個性「パピルス」は、身体をパピルスのように平らに変形させることができる。狭い隙間をすり抜けたり、風に乗って信じられないほどの速度で移動したりすることが可能。湿度の高い場所のカビが弱点である。', tags = ARRAY['長身','褐色肌','お姉さん','超能力']::text[], voice_actor = '宮園拓夢' WHERE character_id = 'CH010698'; -- サラーム
UPDATE characters SET description = '個性：煙幕

揺蕩井煙は元プロヒーローである。彼の個性「煙幕」は、視界を遮る煙の雲を発生させることができる。', tags = ARRAY['おじさん','社会人']::text[], voice_actor = '柿原徹也' WHERE character_id = 'CH010701'; -- 揺蕩井煙
UPDATE characters SET description = '職業：プロヒーロー　個性：黒鞭、ワン・フォー・オール（かつて）

ワン・フォー・オールの5代目継承者で、本来の個性は黒鞭。腕から黒いエネルギーの触手を生み出す個性で、掴む・組み付くのに優れており、機動力を大幅に高めることができた。', tags = ARRAY['黒髪','おじさん','格闘家']::text[], voice_actor = '安元洋貴' WHERE character_id = 'CH010702'; -- 万縄大悟郎
UPDATE characters SET description = 'オール・フォー・ワンの個性：オール・フォー・ワン。職業：ヴィラン。戦闘スタイル：近距離・遠距離対応。

オール・フォー・ワンはヴィラン連合の真の統領であり、庇護者である。かつて日本最強のヴィランであり、オールマイトの宿敵だったが、その真の目的は謎に包まれており、正体も不明である。現在の目標は、死柄木弔を自らの後継者となるべく育成することである。', tags = ARRAY['白髪','長身','おじさん','悪役','クール','ナルシスト','S属性','人外']::text[], voice_actor = '神谷浩史' WHERE character_id = 'CH010690'; -- オール・フォー・ワン
UPDATE characters SET description = '職業：プロヒーロー（元第3位、現在第2位）
個性：猛禽類の翼
所属：ヒーロー公安委員会

鷹見啓悟は気さくで陽気であり、形式的なことを嫌い、自由奔放で予測不可能な行動をすることが多い。同時にうぬぼれが強く、他者を挑発する傾向がある。彼は、プロヒーローは国民からの人気度が最も重要な評価指標だと考えており、公式ランキングを真摯に受け止めていない。むしろ低い順位を好む傾向があり、それにより自由に行動でき、トップヒーローとしての重責から解放されることを望んでいる。彼は気ままなパトロール活動をしながら「気軽に」すごしたいという願いを持っている。', tags = ARRAY['翼','お姉さん','社会人','ナルシスト','マイペース','元気']::text[], voice_actor = '中村悠一' WHERE character_id = 'CH010692'; -- 鷹見啓悟
UPDATE characters SET description = '**個性：多腕**

雄英高校1年A組の生徒。障子目蔵は友好的で優しい性格で、誰とでも上手くやっていける。恨みを持つタイプではなく、不本意に自分を傷つけた者に対しても悪意を向けない。彼は完全に無欲で、誰のためにも命がけで動く覚悟がある。共感力に優れ、相手の気持ちを理解できる一方で、成熟した責任感を備えており、感情的な衝動に駆られて行動することはない。クラスメイトをとても大事にしており、特に彼らが傷ついたり怪我をしたりしたときは保護しようとする。また相当な鈍感さを持ち、自分が怖がられることに慣れていると語っている。', tags = ARRAY['黒髪','高校生','おっとり','真面目','無口','格闘家']::text[], voice_actor = '西田雅一' WHERE character_id = 'CH010693'; -- 障子目蔵
UPDATE characters SET description = '個性：リワインド　壊理は全身に包帯を巻いた少女です。白い半袖のワンピースを着ており、額の右側に小さな角があり、白くて長い、ボサボサの手入れされていない髪をしています。瞳は赤色です。包帯の下には、腕に無数の傷跡があります。', tags = ARRAY['白髪','ロングヘア','赤目','角','包帯','小柄','白肌','幼女']::text[], voice_actor = '小林星蘭' WHERE character_id = 'CH010703'; -- 壊理
UPDATE characters SET description = '志村菜奈は、ワン・フォー・オールの第7代使用者で、オールマイトの師匠であり、グラントリノの親友でした。', tags = ARRAY['老人','ヒロイン']::text[], voice_actor = '園崎未恵' WHERE character_id = 'CH010694'; -- 志村菜奈
UPDATE characters SET description = '個性：帯電

雄英高校1年A組の生徒。上鳴電気は明るく社交的でエネルギッシュな少年で、他の人と一緒に過ごすことが好きだ。一般的に不愛想な爆豪勝己を含め、他の人との関わり方はかなりカジュアルである。上鳴の個性「帯電」は、電気を蓄積して放出することができる。距離を置いて放電することもできるが、上鳴はそれをコントロールする能力がほとんどないため、あらゆる方向に無差別に放電してしまう。また、電気や他の雷系の個性を吸収して無効化することも可能だ。上鳴が限界を超えると', tags = ARRAY['金髪','ショートヘア','高校生','元気','ボーイッシュ']::text[], voice_actor = '畠中祐' WHERE character_id = 'CH010695'; -- 上鳴電気
UPDATE characters SET description = '名前を明かさない男、通称「八斎會組長」は八斎會という組織を統率していた。八斎會組長は、自分の組織が一定の掟と道徳に従うべきだと信じていた。組長は崩壊を司る個性を持つ少年・治崎廻が育つのを見守ったが、やがて治崎廻は組長の理念に反発し、自分自身の主義に従うため組織の実権を奪い、組長を昏睡状態に陥れた。組長は孫娘・エリを治崎廻に引き合わせた人物でもある。', tags = ARRAY['老人','悪役','社会人']::text[], voice_actor = '楠見尚己' WHERE character_id = 'CH010699'; -- 八斎會組長
UPDATE characters SET description = 'リングル王国救命隊の隊長。回復魔法の使い手だが、戦闘能力は非常に高く、かつて騎士団の大隊長を務めていた。回復魔法士のウサトを救命隊に無理やり入隊させ、自分の右腕として鍛え上げる。', tags = ARRAY['お姉さん','クール','真面目','魔法使い','騎士','S属性']::text[] WHERE character_id = 'CH003845'; -- ローズ
UPDATE characters SET description = '何か特別なことを夢見る、ごく普通の高校生。鈴音と和希と一緒に学校から帰宅する途中、リングル王国への召喚に巻き込まれてしまう。治癒魔法の適性があることが判明すると、ローズの救命隊に無理やり入隊させられることになる。そこで、地獄のような訓練を通じて強靭な肉体を手に入れることになるのだった。', tags = ARRAY['黒髪','高校生','真面目','異世界転生','魔法使い']::text[] WHERE character_id = 'CH003844'; -- 兎里健
