UPDATE characters SET description = 'シャウラはフルーゲルによって創造されたプレイアデス監視塔の監督官である。背が高く、暗い緑色の瞳と茶色がかった黒い長髪を持つ。彼女の衣装はスバルのものと似た配色となっており、その衣装のデザインはフルーゲルと彼女の母親から着想を得たものである。シャウラは軽薄で無関心に見られることがあるが、特にスバルに対する場面では深い感情を見せることが判明している。', tags = ARRAY['黒髪','ロングヘア','長身','お姉さん','クール','マイペース']::text[], voice_actor = 'ファイルーズあい' WHERE character_id = 'CH012160'; -- シャウラ
UPDATE characters SET description = '襟ドナは、強欲の魔女エキドナによって創造された人工精霊で、現在アナスタシア・ホーシンに仕えている。第5章で初登場し、第6章で重要な役割を担うことになる。創造主と同様に、襟ドナはエキドナそっくりの話し方、声、振る舞いをしているが、名前以外の過去の記憶がない。このため、スバルは彼女を襟ドナ（襟ドナ）とあだ名で呼ぶようになった。また、アナスタシアを深く思いやっており、彼女たちの状態が他の誰にも知られないよう極限まで尽力する姿勢が見られる。', tags = ARRAY['銀髪','お姉さん','記憶喪失','人外','魔法使い']::text[], voice_actor = '植田佳奈' WHERE character_id = 'CH012165'; -- 襟ドナ
UPDATE characters SET description = 'ペトラ・レイテはイルラム村出身の明るく優しい少女です。ウォルガルム事件からスバルに救われたことをきっかけに、彼のことが大好きになりました。', tags = ARRAY['茶髪','ロングヘア','ロリ','小学生','元気','デレデレ']::text[], voice_actor = '高野麻里佳' WHERE character_id = 'CH012162'; -- ペトラ・レイテ
UPDATE characters SET description = 'ロズワール領の村に住む子どもたちの一人。気が弱い性格だが、スバルに小犬を紹介するなど、心優しい一面を持っている。', tags = ARRAY['ロリ']::text[], voice_actor = '鈴木絵理' WHERE character_id = 'CH012159'; -- メィリィ・ポートルート
UPDATE characters SET description = 'レムはロズワール・L・メザイスに仕える双子のメイドの一人です。右目を隠すくらいの長さの空色の髪、大きな薄い青色の瞳、幼い顔立ちをしています。また、左側の髪にヘアクリップと花形のリボン、メイドヘアバンドを付けています。姉妹のラムとは髪、瞳、リボンの色以外はほぼ同じ外見をしていますが、レムは胸がわずかに大きいため、それを隠すため こっそり採寸を変えています。レムは表面的には丁寧な口調で話す傾向があり、時々~', tags = ARRAY['青髪','ロングヘア','メイド服','小柄','ロリ','ツインテール','リボン','双子','ヒロイン']::text[], voice_actor = '水瀬いのり' WHERE character_id = 'CH012161'; -- レム
UPDATE characters SET description = '魔女教の大罪司教にして怠惰を象徴する存在。', tags = ARRAY['悪役','魔法使い','人外']::text[], voice_actor = '松岡禎丞' WHERE character_id = 'CH012164'; -- ペテルギウス・ロマネコンティ
UPDATE characters SET description = 'レイド・アストレアは、400年前の嫉妬の魔女の封印に携わった最初の剣聖である。', tags = ARRAY['白髪','剣士','おじさん']::text[], voice_actor = '杉田智和' WHERE character_id = 'CH012163'; -- レイド・アストレア
UPDATE characters SET description = 'Twenty-Fifth Baamは、『神之塔』における不規則者であり、物語の主要キャラクターの一人である。彼は親友のレイチェルを探すためにタワーへ入り、ヘドンの試験に合格することで、タワーを登る資格があると判断された。第1部では、レイチェルとの出会い、そしてタワーへの進入前までほぼ人間関係を持たなかったため、人生についての理解が乏しい、非常に共感能力に優れた優しい青年として描かれている。彼は孤独を嫌い、他者の孤独をも苦しみとする。タワーについての知識に乏しく、非常に素朴な性格として考えられている。第1部では、', tags = ARRAY['黒髪','ショタ','天然','おっとり','異世界転生']::text[] WHERE character_id = 'CH013781'; -- Twenty-Fifth Baam
UPDATE characters SET description = '種族：人間
階級：レギュラー
ポジション：ライトベアラー

Aguero Agnis Khunはクン家出身のE級レギュラーで、一般的には「クン」と呼ばれている。彼は『神之塔』の主人公の一人である25代目バムの親友である。

クンは優れた知略を何より頼りにしているが、それだけが彼の強みではない。傑出した身体能力も備えており、ライトベアラーとしての技術も高い。戦闘力についても、その実力は折り紙付きである。', tags = ARRAY['黒髪','ショタ','長身','クール','天才']::text[] WHERE character_id = 'CH013782'; -- Aguero Agnis Khun
UPDATE characters SET description = 'Wangnan Jaは塔全体の王になることを目指している。彼は他の誰の願いよりも、自分の人生における決意を大切にしている。諦めた者たちとは違い、塔の階層を登り続け、塔の真の頂上に到達することを計画している。', tags = ARRAY['真面目','マイペース']::text[] WHERE character_id = 'CH013783'; -- Wangnan Ja
UPDATE characters SET description = 'Michaelは25階で初登場した正規者であり、波動操作者です。クンのチームではヤブ医者を務めており、宣教師とも呼ばれていました。クンとレイチェルを除けば、チーム内での序列は5番目でした。', tags = NULL WHERE character_id = 'CH013825'; -- Michael
UPDATE characters SET description = 'Vespaは蜂をモチーフにした人型の生命体で、シップのチームの複数のメンバーと共に塔を登っている。彼女はかなりの実力を持つ正規ユーザーであり、前衛戦闘員である。ポジションはスカウトで、成人形態への変身能力を持つ。', tags = ARRAY['人外']::text[] WHERE character_id = 'CH013824'; -- Vespa
UPDATE characters SET description = '種族：人間 階級：エクストラ

Rachelは別名ミシェル・ライトといい、バアムの親友であり唯一の友人だった。彼女は「洞窟」にいるバアムを訪ねてくれた唯一の人物だった。彼女は「夜」を恐れているため、塔の頂上で待っているとされる報酬の一つである星々を見ることを望んでいる。', tags = ARRAY['幼馴染','天然']::text[] WHERE character_id = 'CH013784'; -- Rachel
UPDATE characters SET description = 'Ho-Ryang KangはランクがE級のレギュラーで、槍使いである。彼は大柄で無口な男性で、右肩の上に浮かぶ奇妙な紋章を持っており、通常時は片翼の天使のように見える。上半身、そしておそらく下半身も黒い包帯で巻かれており、その包帯にはボタンが付いている。', tags = ARRAY['黒髪','長身','筋肉質','無口','翼','包帯']::text[] WHERE character_id = 'CH013785'; -- Ho-Ryang Kang
UPDATE characters SET description = 'Love Muleは20階のランカーであり管理者である。ミュール一族に生まれ、チキンラブクラブにも所属している。研究協会での試験に合格してウォンスルサとなった。', tags = ARRAY['おじさん','人外']::text[] WHERE character_id = 'CH013835'; -- Love Mule
UPDATE characters SET description = 'Yuri Ha Jahadは、通常ユーリ・ジャハドと呼ばれる（ファミリーネームを付けずに）、ハ・ファミリー出身のハイランカーにしてプリンセスである。特に、彼女は最も有名なプリンセスの一人であり、極めて高く評価されており、塔全体に大きな政治的影響力を持っている。', tags = ARRAY['お姉さん','クール']::text[] WHERE character_id = 'CH013815'; -- Yuri Ha Jahad
