UPDATE characters SET description = 'キシリカ・キシリスは魔族大帝である。彼女は自身の魔眼の力と、他者に魔眼を授与する能力で知られている魔族女帝である。また、不死の魔王バディガディと婚約している。', tags = ARRAY['金目','長身','お姉さん','魔法使い','人外','魔王']::text[] WHERE character_id = 'CH012966'; -- キシリカ・キシリス
