UPDATE characters SET description = 'エリス・ボレアス・グレイラットはルーデウスの遠い親戚にあたる貴族の令嬢です。短気なツンデレキャラクターですが、剣神流の才能を秘めています。', tags = ARRAY['金髪','ツインテール','ツンデレ','ヒロイン','剣士']::text[], voice_actor = '加隈亜衣' WHERE character_id = 'CH012962'; -- エリス・ボレアス・グレイラット
UPDATE characters SET description = 'オルステッドは現在の竜神であり、7大世界権力者の中で第2位の存在だ。ヒトガミの宿敵である。ペルギウスなど他の竜族と同様に、銀髪と金色の三白眼を持ち、圧倒的な迫力を放っている。目立った装備は身につけず、毛皮で飾られた白いコートを纏っている。オルステッドには、その場に存在するだけで全ての生き物に圧倒的な恐怖を与える呪いが掛かっている。だが奇妙なことに、この呪いはルーデウスとナナホシには効果がない。', tags = ARRAY['銀髪','金目','つり目','長身','筋肉質','白肌','クール','悪役','人外']::text[], voice_actor = '津田健次郎' WHERE character_id = 'CH012969'; -- オルステッド
