UPDATE characters SET description = 'ギレーヌ・デドルディアは、かつてのドルディア村長グスターヴの娘であり、エリスの師匠です。また、ルーデウス・グレイラットから魔法をはじめとする様々な教科を学ぶ弟子でもあります。彼女は剣帝となった数少ない人物の一人です。', tags = ARRAY['金髪','ロングヘア','長身','褐色肌','お姉さん','ボーイッシュ','真面目','剣士','魔法使い']::text[], voice_actor = '豊口めぐみ' WHERE character_id = 'CH012964'; -- ギレーヌ・デドルディア
